//! 🛂️ The accepted proof borrows the genuine completion and finished Work from one Source.
use semio_framework_value_control_contract::*;
use semio_framework_value_native_outcome::OriginalConstructionAcceptedProof;
use std::sync::{Arc,Mutex};
#[derive(Default)]
struct Wallet{work:u128,posts:usize,copy:usize}
type Context<'a>=(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn);
struct Work(Arc<Mutex<Wallet>>);
impl OriginalWorkRecipient for Work{
 type Context<'a,'b>=Context<'a> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{c.0.validate(c.1).map_err(Into::into)}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1.identity())}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:OriginalWorkQuote<'r>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'r>where 'b:'a{q.complete(Ok(u128::from(observed)+u128::from(additional)<=self.0.lock().unwrap().work))}
 fn settle_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,q:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 'b:'a{let result=self.validate_context(c);let mut w=self.0.lock().unwrap();w.work=w.work.checked_sub(q.delta()).unwrap();q.complete(result)}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 'b:'a{q.pending()}
}
struct Physical(Arc<Mutex<Wallet>>);
impl OriginalConstructionRecipient for Physical{
 type Context<'a,'b>=Context<'a> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{c.0.validate(c.1).map_err(Into::into)}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1.identity())}
 fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r>where 'b:'a{q.complete(Ok(RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:4096,maximum_capacity_bytes:0,maximum_release_bytes:4096,maximum_depth:8}))}
 fn accept<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,q:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r>where 'b:'a{let result=self.validate_context(c);let mut w=self.0.lock().unwrap();w.posts+=1;w.copy+=q.progress().copied_bytes;q.complete(result)}
 fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{Default::default()}
}
fn finish_work(work:&mut OriginalWork<'_>,action:&mut Option<OriginalWorkActionIdentity>,receipt:&mut Option<OriginalWorkPerformedReceipt>,proof:&mut Option<OriginalWorkActionProof>){
 work.claim_performed_for_action(*action,receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(*action,&mut partial).unwrap());assert!(partial.take().unwrap().source_refusal().is_none());assert!(work.commit_for_action(1,*action,proof).unwrap());
}
#[test]
fn accepted_proof_requires_published_original_and_finished_work(){
 let law:serde_json::Value=serde_json::from_str(include_str!("accepted-proof.json")).unwrap();let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let wallet=Arc::new(Mutex::new(Wallet{work:16,..Default::default()}));let mut work_owner=OriginalWorkAuthority::new(Work(wallet.clone()));let mut physical=OriginalConstructionAuthority::new(Physical(wallet.clone()));let mut foreign=OriginalConstructionAuthority::new(Physical(wallet.clone()));let(mut work_context,mut physical_context,mut foreign_context)=((&issuer,&turn),(&issuer,&turn),(&issuer,&turn));let(mut original,mut payout,mut completion)=(None,None,None);
 work_owner.with_loan(&mut work_context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);physical.with_loan(&mut physical_context,|physical|{
  physical.begin(RetirementDemand{copy_bytes:8,depth:1,..Default::default()},&mut original,&OriginalWorkBorrow::new(&mut work)).unwrap();let original_id=original.as_ref().unwrap().identity();physical.quote(original.as_mut().unwrap()).unwrap();physical.recover_grant(original.as_mut().unwrap()).unwrap().unwrap().unwrap();
  let(mut semantic_action,mut semantic_receipt,mut semantic_proof,mut actual)=(None,None,None,None);assert_eq!(work.prepare_for_action(1,&mut semantic_action).unwrap(),Some(true));work.issue_performed_for_action(semantic_action,&mut semantic_receipt).unwrap();let mut output=0u64;{let mut effect=RetainedAllocationEffect::new(RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:4096,maximum_release_bytes:4096,maximum_depth:8,..Default::default()},1,&mut actual,semantic_receipt.as_mut().unwrap());assert!(effect.performed(1).unwrap());output=7;}assert_eq!(output,7);finish_work(&mut work,&mut semantic_action,&mut semantic_receipt,&mut semantic_proof);physical.post(original.as_mut().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:8,..Default::default()},None).unwrap();assert_eq!(physical.recover_accept(original.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));OriginalWorkBorrow::new(&mut work).finish_retained(&mut semantic_proof,&mut semantic_action).unwrap();
  let(mut payout_action,mut receipt,mut payout_proof)=(None,None,None);physical.begin(OriginalConstructionCompletion::demand(),&mut payout,&OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(payout.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut payout_action).unwrap(),Some(true));work.issue_performed_for_action(payout_action,&mut receipt).unwrap();let progress={let witness=physical.witness(payout.as_ref().unwrap()).unwrap();let mut effect=RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());physical.stage_completion(&mut original,&mut completion,&witness,&mut effect).result.unwrap().unwrap()};finish_work(&mut work,&mut payout_action,&mut receipt,&mut payout_proof);
  {let borrow=OriginalWorkBorrow::new(&mut work);assert_eq!(OriginalConstructionAcceptedProof::authenticate(physical,completion.as_ref().unwrap(),&borrow,semantic_proof.as_ref().unwrap()).unwrap().is_some(),law[2]["valid"].as_bool().unwrap())}
  physical.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(physical.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));assert!(physical.publish_completion(completion.as_mut().unwrap(),payout.as_mut().unwrap(),&OriginalWorkBorrow::new(&mut work),payout_proof.as_ref().unwrap()).unwrap());
  {let borrow=OriginalWorkBorrow::new(&mut work);assert_eq!(OriginalConstructionAcceptedProof::authenticate(physical,completion.as_ref().unwrap(),&borrow,payout_proof.as_ref().unwrap()).unwrap().is_some(),law[4]["valid"].as_bool().unwrap());let proof=OriginalConstructionAcceptedProof::authenticate(physical,completion.as_ref().unwrap(),&borrow,semantic_proof.as_ref().unwrap()).unwrap().unwrap();assert_eq!(law[0]["valid"].as_bool(),Some(true));assert_eq!(proof.action_identity(),original_id);assert_eq!(proof.work_action(),semantic_proof.as_ref().unwrap().action_identity());foreign.with_loan(&mut foreign_context,|other|assert_eq!(OriginalConstructionAcceptedProof::authenticate(other,completion.as_ref().unwrap(),&borrow,semantic_proof.as_ref().unwrap()).unwrap().is_some(),law[1]["valid"].as_bool().unwrap())).unwrap();}
  physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut payout_proof,&mut payout_action).unwrap();drop(semantic_proof.take());
  let demand=completion.as_ref().unwrap().release_demand();physical.begin(demand,&mut payout,&OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(payout.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut payout_action).unwrap(),Some(true));work.issue_performed_for_action(payout_action,&mut receipt).unwrap();let progress={let mut effect=RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());physical.retire_completion(&mut completion,payout.as_ref().unwrap(),&mut effect).result.unwrap().unwrap()};finish_work(&mut work,&mut payout_action,&mut receipt,&mut payout_proof);physical.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(physical.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut payout_proof,&mut payout_action).unwrap();
 }).unwrap()}).unwrap();assert!(completion.is_none());assert_eq!(wallet.lock().unwrap().posts,3);assert!(physical.into_recipient().is_ok());
}
